   for(const [type,label] of Object.entries(labels)){const b=element('button',label,'button secondary');b.type='button';b.onclick=async()=>{const d=catalogDefaults[type],ns=type==='argocd'?'argocd':items[active]?.namespace||'dev',cluster=selectedCluster;for(const button of picker.querySelectorAll('button'))button.disabled=true;try{const name=await newAppName(type,ns,items.map(a=>a.name));if(!picker.isConnected||cluster!==selectedCluster)return;items.push({type,name,namespace:ns,image:d.image,port:d.port,replicas:1,cpu:d.cpu||100,memory:d.memory,storage:d.storage||2,storage_mode:['postgres','redis','kafka','rabbitmq','grafana','prometheus','zabbix','keycloak','elk','loki'].includes(type)?'new':'none',pvc:'',storage_secret:'',mount_path:'/data',host:'',shovel:false});active=items.length-1;draw()}catch(e){if(picker.isConnected)labError(e)}finally{for(const button of picker.querySelectorAll('button'))button.disabled=false}};picker.append(b)}
