  const storageState=()=>{const existing=mode.value==='existing',needsSecret=existing&&['postgres','rabbitmq','grafana','zabbix','keycloak','elk','loki'].includes(type.value);pvc.required=existing;pvc.parentElement.hidden=!existing;secret.required=needsSecret;secret.parentElement.hidden=!needsSecret;mount.required=mode.value!=='none';mount.parentElement.hidden=mode.value==='none';};mode.onchange=storageState;storageState();
