function addStorageFields(type){
 const mode=labField('storage_mode','Хранилище','none','text',[{value:'none',label:'Без PVC (Nginx / свой образ)'},{value:'new',label:'Создать новый PVC'},{value:'existing',label:'Подключить существующий PVC'}]);
 const claim=labField('pvc','Существующий PVC','','text',[]);const mount=labField('mount_path','Путь монтирования (Nginx / свой образ)','/data');const secret=labField('storage_secret','Secret с прежним паролем базы','','text',[]);secret.required=false;
 const note=element('p','PVC доступен только приложению в том же namespace. Новый PVC создаётся в namespace приложения. Существующий PVC подключается без очистки. Версия и формат данных должны соответствовать приложению. Для PostgreSQL, RabbitMQ, Grafana, Zabbix и Keycloak выберите исходный Secret с ключом password. Пароль вручную вводить не нужно. Наличие ключа password не гарантирует, что Secret подходит к данным PVC.','lab-note');$('lab-extra').append(note);
 const update=()=>{const db=['postgres','redis','kafka','rabbitmq','grafana','prometheus','zabbix','keycloak','elk','loki'].includes(type.value);if(db&&mode.value==='none')mode.value='new';claim.parentElement.hidden=mode.value!=='existing';claim.required=mode.value==='existing';$('lab-storage').parentElement.hidden=mode.value!=='new';mount.parentElement.hidden=db||mode.value==='none';secret.parentElement.hidden=mode.value!=='existing'||!['postgres','rabbitmq','grafana','zabbix','keycloak','elk','loki'].includes(type.value);secret.required=!secret.parentElement.hidden;const old=claim.value;claim.replaceChildren();const blank=element('option','Выберите PVC');blank.value='';claim.append(blank);for(const p of pvcData.filter(p=>p.namespace===$('lab-namespace').value)){const o=element('option',p.name+' · '+p.capacity+' · '+p.phase+(p.pods.length?' · занят':''));o.value=p.name;o.disabled=p.phase!=='Bound'||p.pods.length>0;claim.append(o)}if([...claim.options].some(o=>o.value===old))claim.value=old;const previous=secret.value;secret.replaceChildren();const placeholder=element('option','Выберите Secret с ключом password');placeholder.value='';secret.append(placeholder);for(const item of secretData.filter(s=>s.namespace===$('lab-namespace').value&&s.hasPassword)){const option=element('option',item.name+' · '+item.namespace+' · password ✓');option.value=item.name;secret.append(option)}if([...secret.options].some(o=>o.value===previous))secret.value=previous;};
 mode.onchange=update;$('lab-namespace').addEventListener('input',update);update();Promise.all([refreshPVCs(),refreshSecrets()]).then(()=>{if($('lab-dialog').open&&$('lab-storage_mode')===mode)update()});
}
